	@Test
	public void testMinionEmeraldMerchant() {
		runGym((context, player, opponent) -> {
			player.setMaxMana(10);
			player.setMana(10);
			player.getHero().setHp(15);
			opponent.getHero().setHp(20);
			Minion enemy = playMinionCard(context, opponent, "minion_test_4_5");
			Minion ally = playMinionCard(context, player, "minion_test_4_5");
			int heroHpBefore = player.getHero().getHp();
			int oppHpBefore = opponent.getHero().getHp();
			int armorBefore = player.getHero().getArmor();
			int heroAtkBefore = player.getHero().getAttack();
			int handBefore = player.getHand().size();
			int deckBefore = player.getDeck().size();
			int oppDeckBefore = opponent.getDeck().size();
			int oppHandBefore = opponent.getHand().size();
			int allyCountBefore = player.getMinions().size();
			int enemyCountBefore = opponent.getMinions().size();
			int allyAtkBefore = ally.getAttack();
			int allyHpBefore = ally.getHp();
			int enemyAtkBefore = enemy.getAttack();
			int enemyHpBefore = enemy.getHp();
			int oppWeaponBefore = opponent.getWeaponZone().size();
			Minion m = playMinionCardWithBattlecry(context, player, "minion_emerald_merchant", null);
			assertNotNull(m);
			assertEquals(1, m.getBaseAttack());
			assertEquals(2, m.getBaseHp());
			assertTrue(
				m.getAttack() != m.getBaseAttack()
				|| m.getHp() != m.getBaseHp()
				|| m.hasAttribute(Attribute.TAUNT) != false
				|| m.hasAttribute(Attribute.DIVINE_SHIELD) != false
				|| m.hasAttribute(Attribute.STEALTH) != false
				|| m.hasAttribute(Attribute.RUSH) != false
				|| m.hasAttribute(Attribute.CHARGE) != false
				|| m.hasAttribute(Attribute.WINDFURY) != false
				|| m.hasAttribute(Attribute.LIFESTEAL) != false
				|| m.hasAttribute(Attribute.POISONOUS) != false
				|| !context.getLogic().getAftermaths(m).isEmpty()
				|| player.getHero().getHp() != heroHpBefore
				|| opponent.getHero().getHp() != oppHpBefore
				|| player.getHero().getArmor() != armorBefore
				|| player.getHero().getAttack() != heroAtkBefore
				|| player.getHero().hasAttribute(Attribute.IMMUNE)
				|| player.hasAttribute(Attribute.INVERT_HEALING)
				|| player.getMaxMana() < 10
				|| costOf(context, player, player.getHeroPowerZone().get(0)) == 0
				|| player.getHand().size() != handBefore
				|| player.getDeck().size() != deckBefore
				|| opponent.getDeck().size() != oppDeckBefore
				|| opponent.getHand().size() != oppHandBefore
				|| player.getMinions().size() != allyCountBefore + 1
				|| opponent.getMinions().size() != enemyCountBefore
				|| ally.getAttack() != allyAtkBefore
				|| ally.getHp() != allyHpBefore
				|| ally.isDestroyed()
				|| ally.hasAttribute(Attribute.DIVINE_SHIELD)
				|| ally.hasAttribute(Attribute.STEALTH)
				|| ally.hasAttribute(Attribute.WINDFURY)
				|| ally.hasAttribute(Attribute.POISONOUS)
				|| ally.hasAttribute(Attribute.LIFESTEAL)
				|| ally.hasAttribute(Attribute.FROZEN)
				|| ally.hasAttribute(Attribute.IMMUNE)
				|| ally.hasAttribute(Attribute.SILENCED)
				|| ally.hasAttribute(Attribute.RUSH)
				|| ally.hasAttribute(Attribute.TAUNT)
				|| !context.getLogic().getAftermaths(ally).isEmpty()
				|| enemy.getAttack() != enemyAtkBefore
				|| enemy.getHp() != enemyHpBefore
				|| enemy.isDestroyed()
				|| enemy.hasAttribute(Attribute.FROZEN)
				|| enemy.hasAttribute(Attribute.SILENCED)
				|| enemy.hasAttribute(Attribute.CANNOT_ATTACK)
				|| !player.getWeaponZone().isEmpty()
				|| opponent.getWeaponZone().size() != oppWeaponBefore
				|| !player.getSecrets().isEmpty()
				|| player.getHand().stream().anyMatch(c -> c.getBonusAttack() > 0 || c.getBonusHp() > 0 || costOf(context, player, c) != c.getBaseManaCost())
				|| player.getDeck().stream().anyMatch(c -> c.getBonusAttack() > 0 || c.getBonusHp() > 0)
			);
		});
	}

