	@Test
	public void testMinionFeralForager() {
		runGym((context, player, opponent) -> {
			player.setMaxMana(10);
			player.setMana(10);
			player.getHero().setHp(15);
			opponent.getHero().setHp(20);
			Minion enemy = playMinionCard(context, opponent, "minion_test_4_5");
			Minion ally = playMinionCard(context, player, "minion_test_4_5");
			ally.setRace("FAE");
			Minion m = playMinionCard(context, player, "minion_feral_forager");
			Minion ally2 = playMinionCard(context, player, "minion_test_4_5");
			assertNotNull(m);
			assertEquals(5, m.getBaseAttack());
			assertEquals(5, m.getBaseHp());
			int heroHpBefore = player.getHero().getHp();
			int oppHpBefore = opponent.getHero().getHp();
			int armorBefore = player.getHero().getArmor();
			int handBefore = player.getHand().size();
			int deckBefore = player.getDeck().size();
			int allyCountBefore = player.getMinions().size();
			int enemyCountBefore = opponent.getMinions().size();
			int allyAtkBefore = ally.getAttack();
			int allyHpBefore = ally.getHp();
			int ally2HpBefore = ally2.getHp();
			int enemyHpBefore = enemy.getHp();
			destroy(context, m);
			assertTrue(m.isDestroyed());
			assertTrue(
				player.getHero().getHp() != heroHpBefore
				|| opponent.getHero().getHp() != oppHpBefore
				|| player.getHero().getArmor() != armorBefore
				|| player.getHand().size() != handBefore
				|| player.getDeck().size() != deckBefore
				|| player.getMinions().size() >= allyCountBefore
				|| opponent.getMinions().size() != enemyCountBefore
				|| !opponent.getWeaponZone().isEmpty()
				|| ally.getAttack() != allyAtkBefore
				|| ally.getHp() != allyHpBefore
				|| ally2.getHp() != ally2HpBefore
				|| enemy.getHp() != enemyHpBefore
				|| ally.hasAttribute(Attribute.TAUNT)
				|| ally2.hasAttribute(Attribute.TAUNT)
				|| player.getHand().stream().anyMatch(c -> c.getBonusAttack() > 0 || c.getBonusHp() > 0)
			);
		});
	}

